/* Ethereal by HTML5 UP | html5up.net | @ajlkn | CC BY 3.0.
 * Adapted for ImmichPager; composition, typography and accessibility modified. */
.ip-hero { grid-template-columns:minmax(0, 2fr) minmax(0, 3fr); grid-template-areas:'image copy' 'image nav'; padding:0; margin-block:40px; background:linear-gradient(115deg,#726193,#a04c64); box-shadow:0 16px 40px #2e2b3726; }
.ip-hero .ip-header { padding:48px; color:#ffffff; --pager-muted:#ffffff; }
.ip-hero .ip-banner { border-radius:0; }
.ip-hero .ip-navigation { color:#ffffff; padding:20px 48px; }
.ip-title { max-width:14ch; font-size:clamp(var(--pager-title-min-size), calc(1rem + 3vw), var(--pager-title-size)); letter-spacing:-.04em; }
.ip-block { padding-block:40px; }
@media(max-width:760px) { .ip-hero { grid-template-columns:minmax(0,1fr); grid-template-areas:'image' 'copy' 'nav'; margin:0; } .ip-hero .ip-header { padding:32px 24px; } .ip-hero .ip-banner { height:300px; min-height:0; } .ip-hero .ip-navigation { padding:20px 24px; } }

.ip-description { opacity:1; }

.ip-albums:not(.tiles) .ip-album-info p { opacity:1; color:var(--pager-muted); }
.ip-albums.tiles .ip-album-info p { opacity:1; color:#ffffff; }
